E,KAAK,CAAC,SAAS,CAAC,GAAG,EAAE,CAAC,MAAM,CAAC,YAAY,CAAC,UAAU,CAAC,OAAO,CAAC,EAAE,EAAE,CAAC,CAAC;IAEnE,MAAM,UAAU,GAAkB,KAAK,CAAC,WAAW,CAC/C,CAAC,IAAI,EAAE,MAAM,EAAE,EAAE;QACb,MAAM,EAAE,CAAC,IAAI,EAAE,MAAM,CAAC,CAAC;QACvB,kBAAkB,CAAC,KAAK,CAAC,CAAC;QAC1B,oBAAoB,CAAC,OAAO,CAAC,CAAC;QAE9B,MAAM,CAAC,YAAY,CAAC,UAAU,CAAC,OAAO,CAAC,CAAC;QAExC,UAAU,CAAC,OAAO,GAAG,MAAM,CAAC,UAAU,CAAC,GAAG,EAAE;YACxC,kBAAkB,CAAC,IAAI,CAAC,CAAC;QAC7B,CAAC,EAAE,OAAO,CAAC,CAAC;IAChB,CAAC,EACD,CAAC,MAAM,EAAE,OAAO,CAAC,CACpB,CAAC;IAEF,MAAM,YAAY,GAAG,KAAK,CAAC,WAAW,CAAC,GAAG,EAAE;QACxC,IAAI,eAAe,EAAE,CAAC;YAClB,kBAAkB,CAAC,KAAK,CAAC,CAAC;YAC1B,oBAAoB,CAAC,SAAS,CAAC,CAAC;QACpC,CAAC;IACL,CAAC,EAAE,CAAC,eAAe,CAAC,CAAC,CAAC;IAEtB,MAAM,gBAAgB,GAA+C,KAAK,CAAC,WAAW,CAClF,CAAC,KAAK,EAAE,EAAE;QACN,YAAY,EAAE,CAAC,KAAK,CAAC,CAAC;QACtB,YAAY,EAAE,CAAC;IACnB,CAAC,EACD,CAAC,YAAY,EAAE,YAAY,CAAC,CAC/B,CAAC;IAEF,MAAM,WAAW,GAA+C,KAAK,CAAC,WAAW,CAC7E,CAAC,KAAK,EAAE,EAAE;QACN,OAAO,EAAE,CAAC,KAAK,CAAC,CAAC;QACjB,YAAY,EAAE,CAAC;IACnB,CAAC,EACD,CAAC,OAAO,EAAE,YAAY,CAAC,CAC1B,CAAC;IAEF,OAAO,CACH,KAAC,eAAe,IAAC,IAAI,EAAE,IAAI,EAAE,OAAO,EAAE,OAAO,EAAE,MAAM,EAAE,UAAU,YAC5D,CAAC,MAAM,EAAE,EAAE,CAAC,CACT,KAAC,wBAAwB,OACjB,WAAW,EACf,UAAU,EAAE,iBAAiB,EAC7B,UAAU,EAAE,UAAU,IAAI,CAAC,eAAe,EAC1C,MAAM,EAAE,MAAM,EACd,YAAY,EAAE,gBAAgB,EAC9B,OAAO,EAAE,WAAW,GACtB,CACL,GACa,CACrB,CAAC;AACN,CAAC","sourcesContent":["'use client';

import * as React from 'react';

import {ActionTooltip} from '../ActionTooltip';
import {Button} from '../Button';
import type {ButtonButtonProps} from '../Button';
import {ClipboardIcon} from '../ClipboardIcon';
import {CopyToClipboard} from '../CopyToClipboard';
import type {
    CopyToClipboardProps,
    CopyToClipboardStatus,
    OnCopyHandler,
} from '../CopyToClipboard/types';
import {useDefaultProps} from '../theme/useDefaultProps';
import {block} from '../utils/cn';

import i18n from './i18n';

import './ClipboardButton.scss';

const b = block('clipboard-button');

export interface ClipboardButtonProps
    extends Omit<CopyToClipboardProps, 'children'>,
        Omit<ClipboardButtonComponentProps, 'status' | 'closeDelay'> {}

interface ClipboardButtonComponentProps extends Omit<ButtonButtonProps, 'onCopy'> {
    status: CopyToClipboardStatus;
    closeDelay: number | undefined;
    /** Disable tooltip. Tooltip won't be shown */
    hasTooltip?: boolean;
    /** Text shown before copy */
    tooltipInitialText?: string;
    /** Text shown after copy */
    tooltipSuccessText?: string;
    /** Position of clipboard icon */
    iconPosition?: 'start' | 'end';
    /** Custom icon */
    icon?: React.ReactNode;
}

const DEFAULT_TIMEOUT = 1200;

const ClipboardButtonComponent = (props: ClipboardButtonComponentProps) => {
    const {t} = i18n.useTranslation();
    const {
        size = 'm',
        hasTooltip = true,
        tooltipInitialText = t('startCopy'),
        tooltipSuccessText = t('endCopy'),
        status,
        view = 'flat',
        children,
        iconPosition = 'start',
        closeDelay,
        icon,
        ...rest
    } = props;

    const buttonIcon = (
        <Button.Icon className={b('icon')}>
            {icon ?? (({size: iconSize}) => <ClipboardIcon size={iconSize} status={status} />)}
        </Button.Icon>
    );

    return (
        <ActionTooltip
            title={status === 'success' ? tooltipSuccessText : tooltipInitialText}
            disabled={!hasTooltip}
            closeDelay={closeDelay}
        >
            <Button view={view} size={size} aria-label={tooltipInitialText} {...rest}>
                {iconPosition === 'start' ? buttonIcon : null}
                {children}
                {iconPosition === 'end' ? buttonIcon : null}
            </Button>
        </ActionTooltip>
    );
};

export function ClipboardButton(rawProps: ClipboardButtonProps) {
    const props = useDefaultProps('ClipboardButton', rawProps);
    const {
        text,
        timeout = DEFAULT_TIMEOUT,
        onCopy,
        hasTooltip = true,
        onMouseEnter,
        onFocus,
        ...buttonProps
    } = props;

    const timerIdRef = React.useRef<number>();
    const [tooltipCloseDelay, setTooltipCloseDelay] = React.useState<number | undefined>(undefined);
    const [tooltipDisabled, setTooltipDisabled] = React.useState(false);

    React.useEffect(() => window.clearTimeout(timerIdRef.current), []);

    const handleCopy: OnCopyHandler = React.useCallback(
        (text, result) => {
            onCopy?.(text, result);
            setTooltipDisabled(false);
            setTooltipCloseDelay(timeout);

            window.clearTimeout(timerIdRef.current);

            timerIdRef.current = window.setTimeout(() => {
                setTooltipDisabled(true);
            }, timeout);
        },
        [onCopy, timeout],
    );

    const resetTooltip = React.useCallback(() => {
        if (tooltipDisabled) {
            setTooltipDisabled(false);
            setTooltipCloseDelay(undefined);
        }
    }, [tooltipDisabled]);

    const handleMouseEnter: React.MouseEventHandler<HTMLButtonElement> = React.useCallback(
        (event) => {
            onMouseEnter?.(event);
            resetTooltip();
        },
        [onMouseEnter, resetTooltip],
    );

    const handleFocus: React.FocusEventHandler<HTMLButtonElement> = React.useCallback(
        (event) => {
            onFocus?.(event);
            resetTooltip();
        },
        [onFocus, resetTooltip],
    );

    return (
        <CopyToClipboard text={text} timeout={timeout} onCopy={handleCopy}>
            {(status) => (
                <ClipboardButtonComponent
                    {...buttonProps}
                    closeDelay={tooltipCloseDelay}
                    hasTooltip={hasTooltip && !tooltipDisabled}
                    status={status}
                    onMouseEnter={handleMouseEnter}
                    onFocus={handleFocus}
                />
            )}
        </CopyToClipboard>
    );
}
"]}
